import { defineConfig } from 'vite'
import react from '@vitejs/plugin-react'
import tailwindcss from '@tailwindcss/vite'
import { VitePWA } from 'vite-plugin-pwa'

export default defineConfig({
  plugins: [
    react(),
    tailwindcss(),
    VitePWA({
      registerType: 'autoUpdate',
      manifest: {
        name: 'Rhythm — Habit & Stimmung',
        short_name: 'Rhythm',
        description: 'Ein offline-fahiger Habit- und Stimmungs-Tracker.',
        theme_color: '#F7F6F3',
        background_color: '#F7F6F3',
        display: 'standalone',
        start_url: '/',
        icons: [
          { src: '/icon-192.png', sizes: '192x192', type: 'image/png' },
          { src: '/icon-512.png', sizes: '512x512', type: 'image/png' },
          { src: '/icon-512.png', sizes: '512x512', type: 'image/png', purpose: 'any maskable' },
        ],
      },
      workbox: {
        globPatterns: ['**/*.{js,css,html,png,svg,woff2}'],
        runtimeCaching: [
          {
            urlPattern: /^https:\/\/fonts\.googleapis\.com\/.*/i,
            handler: 'CacheFirst',
            options: {
              cacheName: 'google-fonts-cache',
              expiration: { maxEntries: 10, maxAgeSeconds: 60 * 60 * 24 * 365 },
              cacheableResponse: { statuses: [0, 200] },
            },
          },
        ],
      },
    }),
  ],
})

export interface Habit {
  id: string
  name: string
  emoji: string
  color: string
  createdAt: number
}

export interface HabitCompletion {
  habitId: string
  date: string // YYYY-MM-DD
}

export interface MoodEntry {
  date: string // YYYY-MM-DD
  value: number // 1-5
  note?: string
}

import { open } from 'idb'
import type { Habit, HabitCompletion, MoodEntry } from './types'

const DB_NAME = 'rhythm-db'
const DB_VERSION = 1

let dbPromise: Promise<IDBDatabase> | null = null

function getDb() {
  if (!dbPromise) {
    dbPromise = open(DB_NAME, DB_VERSION, (upgrade) => {
      if (upgrade.oldVersion < 1) {
        upgrade.createObjectStore('habits', { keyPath: 'id' })
        upgrade.createObjectStore('completions', { keyPath: 'id', autoIncrement: true })
        upgrade.createObjectStore('moods', { keyPath: 'date' })
      }
    })
  }
  return dbPromise
}

// Habits
export async function getHabits(): Promise<Habit[]> {
  const db = await getDb()
  return db.getAll('habits')
}

export async function addHabit(habit: Omit<Habit, 'id' | 'createdAt'>): Promise<Habit> {
  const db = await getDb()
  const tx = db.transaction('habits', 'readwrite')
  const newHabit: Habit = {
    ...habit,
    id: crypto.randomUUID(),
    createdAt: Date.now(),
  }
  await tx.store.put(newHabit)
  await tx.done
  return newHabit
}

export async function updateHabit(id: string, updates: Partial<Omit<Habit, 'id' | 'createdAt'>>): Promise<void> {
  const db = await getDb()
  const tx = db.transaction('habits', 'readwrite')
  const habit = await tx.store.get(id)
  if (habit) {
    await tx.store.put({ ...habit, ...updates })
  }
  await tx.done
}

export async function deleteHabit(id: string): Promise<void> {
  const db = await getDb()
  const tx = db.transaction(['habits', 'completions'], 'readwrite')
  await tx.store.get('habits', id).then((h) => { if (h) tx.store.delete(id) })
  const completionsStore = tx.objectStore('completions')
  const allCompletions = await completionsStore.getAll()
  for (const c of allCompletions) {
    if (c.habitId === id) await completionsStore.delete(c.id)
  }
  await tx.done
}

// Completions
export async function getCompletions(): Promise<HabitCompletion[]> {
  const db = await getDb()
  return db.getAll('completions')
}

export async function getCompletionForDate(habitId: string, date: string): Promise<HabitCompletion | null> {
  const db = await getDb()
  const tx = db.transaction('completions', 'readonly')
  const all = await tx.store.getAll()
  return all.find((c) => c.habitId === habitId && c.date === date) ?? null
}

export async function toggleCompletion(habitId: string, date: string): Promise<void> {
  const db = await getDb()
  const existing = await getCompletionForDate(habitId, date)
  const tx = db.transaction('completions', 'readwrite')
  if (existing) {
    await tx.store.delete(existing.id)
  } else {
    await tx.store.add({ habitId, date })
  }
  await tx.done
}

// Moods
export async function getMoods(): Promise<MoodEntry[]> {
  const db = await getDb()
  return db.getAll('moods')
}

export async function getMoodForDate(date: string): Promise<MoodEntry | null> {
  const db = await getDb()
  return db.get('moods', date)
}

export async function saveMood(entry: Omit<MoodEntry, 'date'> & { date: string }): Promise<void> {
  const db = await getDb()
  await db.put('moods', entry)
}

// Streak calculation (pure function, no DB needed)
export function calcStreak(habits: Habit[], completions: HabitCompletion[]): Record<string, { current: number; best: number }> {
  const result: Record<string, { current: number; best: number }> = {}

  for (const habit of habits) {
    const dates = completions
      .filter((c) => c.habitId === habit.id)
      .map((c) => c.date)
      .sort()

    let current = 0
    let best = 0
    let temp = 0
    const today = new Date()
    today.setHours(0, 0, 0, 0)

    // Calculate current streak
    const dateSet = new Set(dates)
    let d = new Date(today)
    // Check if today is completed; if not, start from yesterday
    const todayStr = formatDate(today)
    if (!dateSet.has(todayStr)) {
      d.setDate(d.getDate() - 1)
    }
    while (true) {
      const ds = formatDate(d)
      if (dateSet.has(ds)) {
        current++
        d.setDate(d.getDate() - 1)
      } else {
        break
      }
    }

    // Calculate best streak
    if (dates.length > 0) {
      const sorted = [...new Set(dates)].sort()
      temp = 1
      for (let i = 1; i < sorted.length; i++) {
        const prev = new Date(sorted[i - 1]!)
        const curr = new Date(sorted[i]!)
        prev.setHours(0, 0, 0, 0)
        curr.setHours(0, 0, 0, 0)
        const diff = (curr.getTime() - prev.getTime()) / (1000 * 60 * 60 * 24)
        if (diff === 1) {
          temp++
        } else {
          temp = 1
        }
        best = Math.max(best, temp)
      }
    }

    result[habit.id] = { current, best }
  }

  return result
}

function formatDate(d: Date): string {
  const y = d.getFullYear()
  const m = String(d.getMonth() + 1).padStart(2, '0')
  const day = String(d.getDate()).padStart(2, '0')
  return `${y}-${m}-${day}`
}

export function getTodayStr(): string {
  return formatDate(new Date())
}

export function getLast7Days(): string[] {
  const days: string[] = []
  const today = new Date()
  for (let i = 6; i >= 0; i--) {
    const d = new Date(today)
    d.setDate(d.getDate() - i)
    days.push(formatDate(d))
  }
  return days
}

export function getDayLabel(dateStr: string): string {
  const d = new Date(dateStr + 'T00:00:00')
  const today = new Date()
  today.setHours(0, 0, 0, 0)
  const yesterday = new Date(today)
  yesterday.setDate(yesterday.getDate() - 1)
  const tomorrow = new Date(today)
  tomorrow.setDate(tomorrow.getDate() + 1)

  if (dateStr === formatDate(today)) return 'Heute'
  if (dateStr === formatDate(yesterday)) return 'Gestern'
  if (dateStr === formatDate(tomorrow)) return 'Morgen'

  return d.toLocaleDateString('de-DE', { weekday: 'short' })
}

import { useState, useEffect, useCallback } from 'react'
import type { Habit, MoodEntry } from './types'
import {
  getHabits, addHabit, updateHabit, deleteHabit,
  getCompletions, toggleCompletion,
  getMoods, getMoodForDate, saveMood,
  calcStreak, getTodayStr,
} from './db'

export function useHabits() {
  const [habits, setHabits] = useState<Habit[]>([])
  const [completions, setCompletions] = useState<{ habitId: string; date: string }[]>([])
  const [streaks, setStreaks] = useState<Record<string, { current: number; best: number }>>({})
  const [loading, setLoading] = useState(true)

  const load = useCallback(async () => {
    const [h, c] = await Promise.all([getHabits(), getCompletions()])
    setHabits(h)
    setCompletions(c)
    setStreaks(calcStreak(h, c))
    setLoading(false)
  }, [])

  useEffect(() => { load() }, [load])

  const add = useCallback(async (data: Omit<Habit, 'id' | 'createdAt'>) => {
    const h = await addHabit(data)
    setHabits((prev) => [...prev, h])
  }, [])

  const update = useCallback(async (id: string, updates: Partial<Omit<Habit, 'id' | 'createdAt'>>) => {
    await updateHabit(id, updates)
    const h = await getHabits()
    const c = await getCompletions()
    setHabits(h)
    setCompletions(c)
    setStreaks(calcStreak(h, c))
  }, [])

  const remove = useCallback(async (id: string) => {
    await deleteHabit(id)
    const h = await getHabits()
    const c = await getCompletions()
    setHabits(h)
    setCompletions(c)
    setStreaks(calcStreak(h, c))
  }, [])

  const toggle = useCallback(async (habitId: string, date: string) => {
    await toggleCompletion(habitId, date)
    const h = await getHabits()
    const c = await getCompletions()
    setHabits(h)
    setCompletions(c)
    setStreaks(calcStreak(h, c))
  }, [])

  return { habits, completions, streaks, loading, add, update, remove, toggle }
}

export function useMood() {
  const [moods, setMoods] = useState<MoodEntry[]>([])
  const [todayMood, setTodayMood] = useState<MoodEntry | null>(null)
  const [loading, setLoading] = useState(true)

  const load = useCallback(async () => {
    const all = await getMoods()
    setMoods(all)
    const today = getTodayStr()
    const m = await getMoodForDate(today)
    setTodayMood(m)
    setLoading(false)
  }, [])

  useEffect(() => { load() }, [load])

  const save = useCallback(async (entry: Omit<MoodEntry, 'date'> & { date: string }) => {
    await saveMood(entry)
    const all = await getMoods()
    setMoods(all)
    if (entry.date === getTodayStr()) {
      setTodayMood(entry)
    }
  }, [])

  return { moods, todayMood, loading, save }
}

export function useDarkMode() {
  const [dark, setDark] = useState(() => {
    const stored = localStorage.getItem('rhythm-dark')
    if (stored !== null) return stored === 'true'
    return window.matchMedia('(prefers-color-scheme: dark)').matches
  })

  useEffect(() => {
    document.documentElement.classList.toggle('dark', dark)
    localStorage.setItem('rhythm-dark', String(dark))
  }, [dark])

  const toggle = useCallback(() => setDark((d) => !d), [])

  return { dark, toggle }
}

import { useState } from 'react'
import Today from './components/Today'
import Week from './components/Week'
import Settings from './components/Settings'
import BottomNav from './components/BottomNav'

type Tab = 'today' | 'week' | 'settings'

function App() {
  const [active, setActive] = useState<Tab>('today')

  return (
    <div className="min-h-screen bg-stone-50 dark:bg-stone-950 text-stone-800 dark:text-stone-200 transition-colors duration-200">
      <div className="max-w-md mx-auto pb-24">
        {active === 'today' && <Today />}
        {active === 'week' && <Week />}
        {active === 'settings' && <Settings />}
      </div>
      <BottomNav active={active} onTabChange={setActive} />
    </div>
  )
}

export default App

import type { Tab } from '../App'

interface Props {
  active: Tab
  onTabChange: (tab: Tab) => void
}

export default function BottomNav({ active, onTabChange }: Props) {
  const tabs: { id: Tab; label: string; icon: string }[] = [
    { id: 'today', label: 'Heute', icon: todayIcon },
    { id: 'week', label: 'Woche', icon: weekIcon },
    { id: 'settings', label: 'Einstellungen', icon: settingsIcon },
  ]

  return (
    <nav className="fixed bottom-0 left-0 right-0 bg-white/80 dark:bg-stone-900/80 backdrop-blur-lg border-t border-stone-200 dark:border-stone-800">
      <div className="max-w-md mx-auto flex">
        {tabs.map((tab) => {
          const isActive = active === tab.id
          return (
            <button
              key={tab.id}
              onClick={() => onTabChange(tab.id)}
              className="flex-1 flex flex-col items-center justify-center py-3 gap-0.5 min-h-[48px] touch-manipulation"
              aria-label={tab.label}
              aria-current={isActive ? 'page' : undefined}
            >
              <span className={`transition-colors duration-150 ${isActive ? 'text-stone-900 dark:text-stone-100' : 'text-stone-400 dark:text-stone-500'}`}>
                {tab.icon}
              </span>
              <span className={`text-xs transition-colors duration-150 ${isActive ? 'text-stone-900 dark:text-stone-100 font-medium' : 'text-stone-400 dark:text-stone-500'}`}>
                {tab.label}
              </span>
            </button>
          )
        })}
      </div>
    </nav>
  )
}

