import { useState, useEffect } from 'react'
import { useHabits } from '../hooks'
import MoodSection from './MoodSection'
import { getTodayStr, getDayLabel } from '../db'

export default function Today() {
  const { habits, completions, streaks, loading, toggle } = useHabits()
  const today = getTodayStr()
  const [animating, setAnimating] = useState<Record<string, boolean>>({})

  useEffect(() => {
    const timer = setTimeout(() => setAnimating({}), 400)
    return () => clearTimeout(timer)
  }, [completions])

  const handled = completions.filter((c) => c.date === today).map((c) => c.habitId)
  const progress = habits.length > 0 ? `${handled.length} von ${habits.length}` : ''

  if (loading) {
    return (
      <div className="px-5 pt-12 pb-4">
        <div className="h-8 w-32 bg-stone-200 dark:bg-stone-800 rounded-lg animate-pulse mb-3" />
        <div className="h-5 w-24 bg-stone-200 dark:bg-stone-800 rounded-lg animate-pulse mb-8" />
        {[1, 2, 3].map((i) => (
          <div key={i} className="h-16 bg-stone-200 dark:bg-stone-800 rounded-xl animate-pulse mb-3" />
        ))}
      </div>
    )
  }

  if (habits.length === 0) {
    return (
      <div className="px-5 pt-12 pb-4">
        <header className="mb-8">
          <h1 className="text-3xl font-light tracking-tight text-stone-900 dark:text-stone-100">
            {getDayLabel(today)}
          </h1>
          <p className="text-stone-400 dark:text-stone-500 mt-1 text-sm">Noch keine Habits.</p>
        </header>
        <div className="flex flex-col items-center justify-center py-20 text-center">
          <div className="w-16 h-16 rounded-2xl bg-stone-100 dark:bg-stone-900 flex items-center justify-center mb-4">
            <svg width="28" height="28" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.5" className="text-stone-300 dark:text-stone-600">
              <path d="M12 5v14M5 12h14" strokeLinecap="round" />
            </svg>
          </div>
          <p className="text-stone-500 dark:text-stone-400 text-sm leading-relaxed max-w-xs">
            Wechsle zu Einstellungen und lege deinen ersten Habit an.
          </p>
        </div>
        <MoodSection />
      </div>
    )
  }

  return (
    <div className="px-5 pt-12 pb-4">
      <header className="mb-8">
        <h1 className="text-3xl font-light tracking-tight text-stone-900 dark:text-stone-100">
          {getDayLabel(today)}
        </h1>
        <p className="text-stone-400 dark:text-stone-500 mt-1 text-sm">{progress}</p>
      </header>

      <div className="space-y-2 mb-8">
        {habits.map((habit, idx) => {
          const done = handled.includes(habit.id)
          const streak = streaks[habit.id]
          const isAnimating = animating[habit.id]

          return (
            <button
              key={habit.id}
              onClick={() => {
                toggle(habit.id, today)
                setAnimating((prev) => ({ ...prev, [habit.id]: true }))
              }}
              className={`w-full flex items-center gap-4 px-4 py-3.5 rounded-xl border transition-all duration-200 touch-manipulation text-left ${
                done
                  ? 'border-stone-200 dark:border-stone-800 bg-white dark:bg-stone-900'
                  : 'border-stone-200 dark:border-stone-800 bg-white dark:bg-stone-900 opacity-70 hover:opacity-100'
              } ${isAnimating ? 'scale-[0.97]' : 'scale-100'}`}
              style={{ animation: isAnimating ? 'pop 0.2s ease-out' : undefined }}
              aria-pressed={done}
            >
              <span
                className="w-10 h-10 rounded-xl flex items-center justify-center text-lg flex-shrink-0"
                style={{ backgroundColor: `${habit.color}20` }}
              >
                {habit.emoji}
              </span>
              <div className="flex-1 min-w-0">
                <p className={`font-medium truncate ${done ? 'text-stone-900 dark:text-stone-100' : 'text-stone-600 dark:text-stone-400'}`}>
                  {habit.name}
                </p>
                {streak.current > 0 && (
                  <p className="text-xs text-stone-400 dark:text-stone-500 mt-0.5">
                    {streak.current} Tag{streak.current !== 1 ? 'e' : ''} · Best: {streak.best}
                  </p>
                )}
              </div>
              <span
                className={`w-7 h-7 rounded-full border-2 flex items-center justify-center flex-shrink-0 transition-all duration-200 ${
                  done
                    ? 'border-transparent'
                    : 'border-stone-200 dark:border-stone-700'
                }`}
                style={done ? { backgroundColor: habit.color } : undefined}
              >
                {done && (
                  <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="white" strokeWidth="3" strokeLinecap="round" strokeLinejoin="round">
                    <polyline points="20 6 9 17 4 12" />
                  </svg>
                )}
              </span>
            </button>
          )
        })}
      </div>

      <MoodSection />

      <style>{`
        @keyframes pop {
          0% { transform: scale(1); }
          50% { transform: scale(0.95); }
          100% { transform: scale(1); }
        }
      `}</style>
    </div>
  )
}

import { useState, useEffect } from 'react'
import { useMood } from '../hooks'
import { getTodayStr, getDayLabel } from '../db'

const MOODS = [
  { value: 1, emoji: '😔', label: 'Sehr schlecht' },
  { value: 2, emoji: '😕', label: 'Schlecht' },
  { value: 3, emoji: '😐', label: 'Okay' },
  { value: 4, emoji: '🙂', label: 'Gut' },
  { value: 5, emoji: '😊', label: 'Sehr gut' },
] as const

export default function MoodSection() {
  const { todayMood, save } = useMood()
  const [selected, setSelected] = useState<number | null>(todayMood?.value ?? null)
  const [note, setNote] = useState(todayMood?.note ?? '')
  const [saved, setSaved] = useState(false)

  useEffect(() => {
    setSelected(todayMood?.value ?? null)
    setNote(todayMood?.note ?? '')
    setSaved(false)
  }, [todayMood])

  const handleSave = () => {
    if (selected === null) return
    save({ date: getTodayStr(), value: selected, note: note.trim() || undefined })
    setSaved(true)
  }

  return (
    <section className="mt-2">
      <h2 className="text-sm font-medium text-stone-400 dark:text-stone-500 uppercase tracking-widest mb-3">
        Stimmung
      </h2>
      <div className="bg-white dark:bg-stone-900 border border-stone-200 dark:border-stone-800 rounded-xl p-4">
        <div className="flex gap-2 mb-3">
          {MOODS.map((m) => (
            <button
              key={m.value}
              onClick={() => setSelected(m.value)}
              className={`flex-1 flex flex-col items-center gap-1 py-2 rounded-lg transition-all duration-150 touch-manipulation ${
                selected === m.value
                  ? 'bg-stone-100 dark:bg-stone-800'
                  : 'hover:bg-stone-50 dark:hover:bg-stone-950'
              }`}
              aria-label={m.label}
              aria-pressed={selected === m.value}
            >
              <span className="text-2xl leading-none">{m.emoji}</span>
              <span className={`text-xs ${selected === m.value ? 'text-stone-700 dark:text-stone-300' : 'text-stone-400 dark:text-stone-600'}`}>
                {m.label}
              </span>
            </button>
          ))}
        </div>
        <input
          type="text"
          value={note}
          onChange={(e) => setNote(e.target.value)}
          placeholder="Optional: Notiz…"
          maxLength={200}
          className="w-full text-sm bg-transparent border-b border-stone-200 dark:border-stone-800 pb-1 text-stone-700 dark:text-stone-300 placeholder-stone-300 dark:placeholder-stone-700 focus:outline-none focus:border-stone-400 dark:focus:border-stone-600 transition-colors mb-3"
        />
        <button
          onClick={handleSave}
          disabled={selected === null}
          className={`w-full py-2.5 rounded-lg text-sm font-medium transition-all duration-150 touch-manipulation ${
            selected !== null
              ? 'bg-stone-900 dark:bg-stone-100 text-white dark:text-stone-900 hover:bg-stone-700 dark:hover:bg-stone-200'
              : 'bg-stone-100 dark:bg-stone-800 text-stone-300 dark:text-stone-600 cursor-not-allowed'
          }`}
        >
          {saved ? 'Gespeichert' : 'Speichern'}
        </button>
      </div>
    </section>
  )
}

import { useMemo } from 'react'
import { useHabits } from '../hooks'
import { useMood } from '../hooks'
import { getLast7Days, getDayLabel } from '../db'
import {
  ResponsiveContainer,
  BarChart,
  Bar,
  XAxis,
  YAxis,
  CartesianGrid,
  Tooltip,
  LineChart,
  Line,
} from 'recharts'

export default function Week() {
  const { habits, completions } = useHabits()
  const { moods } = useMood()
  const days = getLast7Days()

  const habitData = useMemo(() => {
    return days.map((date) => {
      const count = completions.filter((c) => c.date === date).length
      return { date, done: count, label: getDayLabel(date) }
    })
  }, [days, completions])

  const moodData = useMemo(() => {
    return days.map((date) => {
      const m = moods.find((m) => m.date === date)
      return { date, mood: m?.value ?? null, label: getDayLabel(date) }
    })
  }, [days, moods])

  const emptyHabits = habits.length === 0
  const emptyMoods = moods.length === 0

  return (
    <div className="px-5 pt-12 pb-4">
      <header className="mb-8">
        <h1 className="text-3xl font-light tracking-tight text-stone-900 dark:text-stone-100">
          Diese Woche
        </h1>
        <p className="text-stone-400 dark:text-stone-500 mt-1 text-sm">
          {days[0]} bis {days[6]}
        </p>
      </header>

      <section className="mb-8">
        <h2 className="text-sm font-medium text-stone-400 dark:text-stone-500 uppercase tracking-widest mb-3">
          Erledigte Habits
        </h2>
        {emptyHabits ? (
          <div className="bg-white dark:bg-stone-900 border border-stone-200 dark:border-stone-800 rounded-xl p-8 text-center">
            <p className="text-stone-400 dark:text-stone-600 text-sm">
              Lege Habits an, um sie hier zu sehen.
            </p>
          </div>
        ) : (
          <div className="bg-white dark:bg-stone-900 border border-stone-200 dark:border-stone-800 rounded-xl p-4">
            <ResponsiveContainer width="100%" height={160}>
              <BarChart data={habitData} margin={{ top: 8, right: 8, left: -20, bottom: 0 }}>
                <CartesianGrid strokeDasharray="3 3" stroke="currentColor" className="text-stone-200 dark:text-stone-800" vertical={false} />
                <XAxis
                  dataKey="label"
                  tick={{ fontSize: 11, fill: 'currentColor', className: 'text-stone-400 dark:text-stone-600' }}
                  axisLine={false}
                  tickLine={false}
                />
                <YAxis
                  hide
                  domain={[0, Math.max(habits.length, 3)]}
                />
                <Tooltip
                  contentStyle={{
                    backgroundColor: 'currentColor',
                    color: 'var(--tw-color-stone-900, #1c1917)',
                    borderRadius: 8,
                    border: 'none',
                    fontSize: 12,
                  }}
                  labelStyle={{ fontWeight: 600 }}
                  formatter={(value: number) => [`${value} von ${habits.length}`, 'Erledigt']}
                />
                <Bar
                  dataKey="done"
                  fill="currentColor"
                  className="text-stone-800 dark:text-stone-200"
                  radius={[4, 4, 0, 0]}
                  barSize={28}
                />
              </BarChart>
